"""Real English word frequencies, embedded (no network, no keys).

Source: Google web/books 1-gram counts (Norvig count_1w, 333k
words, 333B tokens). ``LOGP`` maps the 15,000 most frequent
real words to -log2(frequency) (smaller = more common);
``COMMON_5000`` is a curated 5,000-word common core (web-spam,
brand and profanity tokens removed).

Real AI detectors weigh this: models over-produce mid-frequency
formal vocabulary ("training echoes"), while people stay in the
common core. Rare-word density and mean surprisal are computed
from this table in detectors.py.
"""

